import 'package:flutter/material.dart';
import '../bridge.dart';
import '../theme/app_theme.dart';
import '../widgets/app_ui.dart';

class AnalyticsScreen extends StatefulWidget{const AnalyticsScreen({super.key,required this.bridge});final NanishiniBridge bridge;@override State<AnalyticsScreen> createState()=>_AnalyticsState();}
class _AnalyticsState extends State<AnalyticsScreen>{late DateTime month=DateTime(DateTime.now().year,DateTime.now().month);late Future<MonthlyDashboard> future=load();Future<MonthlyDashboard> load()=>widget.bridge.loadMonthlyDashboard(month.year,month.month);
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('分析')),body:FutureBuilder<MonthlyDashboard>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:OutlinedButton(onPressed:(){final nextFuture=load();setState((){future=nextFuture;});},child:const Text('もう一度試す')));return _Content(data:s.data!,month:month,onMonth:(m)=>setState((){month=m;future=load();}));}));}

class _Content extends StatelessWidget{const _Content({required this.data,required this.month,required this.onMonth});final MonthlyDashboard data;final DateTime month;final ValueChanged<DateTime> onMonth;
  int get rate=>data.launchCount==0?0:((data.launchCount-data.noPurposeCount)*100/data.launchCount).round();
  int get previousRate=>data.previousLaunchCount==0?0:((data.previousLaunchCount-data.previousNoPurposeCount)*100/data.previousLaunchCount).round();
  @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.fromLTRB(20,0,20,32),children:[
    _MonthPicker(month:month,earliest:data.earliestMonth,onChanged:onMonth),const SizedBox(height:26),
    Text(data.launchCount==0?'この月の記録はまだありません':'今月は $rate% の起動に\n目的がありました',style:Theme.of(context).textTheme.headlineMedium),
    if(data.previousLaunchCount>0)Padding(padding:const EdgeInsets.only(top:8),child:Text('${rate-previousRate>=0?'+':''}${rate-previousRate}pt 先月比',style:TextStyle(color:rate>=previousRate?checkpointGreen:checkpointOrange,fontWeight:FontWeight.w600))),
    const SizedBox(height:20),Row(children:[_small(context,'起動回数','${data.launchCount}回'),const SizedBox(width:32),_small(context,'利用時間',formatDuration(data.totalUsageSeconds))]),
    const SizedBox(height:32),_Trend(daily:data.daily),const SizedBox(height:34),
    Text('目的なく開きやすいアプリ',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),
    if(data.noPurposeApps.isEmpty)const EmptyState('該当する記録はありません')else for(var i=0;i<data.noPurposeApps.length;i++)ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(backgroundColor:const Color(0xFFFFF3E4),foregroundColor:checkpointOrange,child:Text('${i+1}')),title:Text(data.noPurposeApps[i].applicationLabel),trailing:Text('${data.noPurposeApps[i].launchCount}回')),
    const SizedBox(height:28),Text('何のために開いている？',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),_Breakdown(items:data.purposeCategories,total:data.launchCount),
    const SizedBox(height:32),Text('詳しい利用データ',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),
    _Detail(title:'利用時間が長いアプリ',children:[for(final a in data.topByUsage)ListTile(title:Text(a.applicationLabel),subtitle:Text('${a.launchCount}回起動'),trailing:Text(formatDuration(a.usageSeconds)))]),
    _Detail(title:'よく開いたアプリ',children:[for(final a in data.topByLaunches)ListTile(title:Text(a.applicationLabel),subtitle:Text(formatDuration(a.usageSeconds)),trailing:Text('${a.launchCount}回'))]),
    _Detail(title:'具体的な利用目的',children:[for(final p in data.purposes.take(7))ListTile(title:Text(p.label),trailing:Text('${p.launchCount}回'))]),
    _Detail(title:'開く前にしていたこと',children:[for(final a in data.activityCategories)ListTile(title:Text(a.label),trailing:Text('${a.launchCount}回'))]),
    _Detail(title:'最近の利用',children:[for(final r in data.recent)ListTile(title:Text('${formatClock(r.startedAt)}  ${r.applicationLabel}'),subtitle:Text(r.purposeText.isEmpty?'目的未設定':r.purposeText),trailing:Text(formatDuration(r.actualUsageSeconds)))]),
  ]);
  Widget _small(BuildContext c,String l,String v)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(l,style:Theme.of(c).textTheme.bodySmall),const SizedBox(height:3),Text(v,style:Theme.of(c).textTheme.titleLarge)]);
}
class _MonthPicker extends StatelessWidget{const _MonthPicker({required this.month,required this.earliest,required this.onChanged});final DateTime month;final String? earliest;final ValueChanged<DateTime> onChanged;@override Widget build(BuildContext context){final now=DateTime.now();final parts=earliest?.split('-');final start=parts?.length==2?DateTime(int.parse(parts![0]),int.parse(parts[1])):DateTime(now.year,now.month);final count=((now.year-start.year)*12+now.month-start.month+1).clamp(1,1200);return Align(alignment:Alignment.centerLeft,child:PopupMenuButton<DateTime>(onSelected:onChanged,itemBuilder:(_)=>List.generate(count,(i){final d=DateTime(now.year,now.month-i);return PopupMenuItem(value:d,child:Text('${d.year}年${d.month}月'));}),child:Row(mainAxisSize:MainAxisSize.min,children:[Text('${month.year}年${month.month}月',style:Theme.of(context).textTheme.titleMedium),const Icon(Icons.expand_more_rounded)])));}}
enum _Metric{purpose,time,launches}
class _Trend extends StatefulWidget{const _Trend({required this.daily});final List<DailyUsage> daily;@override State<_Trend> createState()=>_TrendState();}
class _TrendState extends State<_Trend>{_Metric metric=_Metric.purpose;@override Widget build(BuildContext context){final values=widget.daily.map((d)=>switch(metric){_Metric.purpose=>d.launchCount==0?0:(d.purposeCount*100/d.launchCount).round(),_Metric.time=>d.usageSeconds,_Metric.launches=>d.launchCount}).toList();final max=metric==_Metric.purpose?100:values.fold(0,(a,b)=>b>a?b:a);return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('今月の利用推移',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:SegmentedButton<_Metric>(showSelectedIcon:false,segments:const[ButtonSegment(value:_Metric.purpose,label:Text('目的あり率')),ButtonSegment(value:_Metric.time,label:Text('利用時間')),ButtonSegment(value:_Metric.launches,label:Text('起動回数'))],selected:{metric},onSelectionChanged:(v)=>setState(()=>metric=v.first))),const SizedBox(height:18),SizedBox(height:170,child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:[for(var i=0;i<values.length;i++)Expanded(child:Tooltip(message:'${i+1}日 ${metric==_Metric.purpose?'${values[i]}%':values[i]}',child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Container(height:max==0?2:120*values[i]/max,margin:const EdgeInsets.symmetric(horizontal:1),decoration:BoxDecoration(color:checkpointGreen,borderRadius:BorderRadius.circular(3))),const SizedBox(height:5),Text(i==0||(i+1)%5==0?'${i+1}':'',style:const TextStyle(fontSize:9))])))]))]);}}
class _Breakdown extends StatelessWidget{const _Breakdown({required this.items,required this.total});final List<UsageBreakdown> items;final int total;@override Widget build(BuildContext context)=>Column(children:[if(items.isEmpty)const EmptyState('この月の記録はありません')else for(final i in items)Padding(padding:const EdgeInsets.symmetric(vertical:7),child:Row(children:[SizedBox(width:110,child:Text(i.label,overflow:TextOverflow.ellipsis)),Expanded(child:LinearProgressIndicator(value:total==0?0:i.launchCount/total,minHeight:7,borderRadius:BorderRadius.circular(8))),const SizedBox(width:10),Text('${total==0?0:(i.launchCount*100/total).round()}%')]))]);}
class _Detail extends StatelessWidget{const _Detail({required this.title,required this.children});final String title;final List<Widget> children;@override Widget build(BuildContext context)=>ExpansionTile(tilePadding:EdgeInsets.zero,title:Text(title),children:children.isEmpty?[const EmptyState('記録はありません')]:children);}
